use chrono::{DateTime, Local, LocalResult, TimeZone, Utc};
use filesize::file_real_size_fast;
use nu_glob::Pattern;
use nu_protocol::{record, Record, ShellError, Signals, Span, Value};
use std::path::{Path, PathBuf};
use std::time::{SystemTime, UNIX_EPOCH};

#[cfg(unix)]
use std::os::unix::fs::FileTypeExt;

#[derive(Debug, Clone)]
pub struct DirBuilder {
    pub tag: Span,
    pub min: Option<u64>,
    pub deref: bool,
    pub exclude: Option<Pattern>,
    pub all: bool,
}

impl DirBuilder {
    pub fn new(
        tag: Span,
        min: Option<u64>,
        deref: bool,
        exclude: Option<Pattern>,
        all: bool,
    ) -> DirBuilder {
        DirBuilder {
            tag,
            min,
            deref,
            exclude,
            all,
        }
    }

    #[allow(clippy::too_many_arguments)]
    pub(crate) fn dir_entry_dict(
        &self,
        filename: &Path,
        display_name: &str,
        metadata: Option<&std::fs::Metadata>,
        span: Span,
        long: bool,
        du: bool,
        signals: &Signals,
        use_mime_type: bool,
    ) -> Result<Value, ShellError> {
        #[cfg(windows)]
        if metadata.is_none() {
            return Ok(windows_helper::dir_entry_dict_windows_fallback(
                filename,
                display_name,
                span,
                long,
            ));
        }

        let mut record = Record::new();

        record.push("name", Value::string(display_name, span));

        if let Some(md) = metadata {
            let file_type = get_file_type(md, display_name, use_mime_type);
            record.push("type", Value::string(file_type, span));
        } else {
            record.push("type", Value::nothing(span));
        }

        let apparent_size = metadata.and_then(|md| apparent_listing_size(md, filename));
        let file_info = FileInfo {
            path: filename.to_path_buf(),
            size: apparent_size.unwrap_or(0),
            blocks: apparent_size,
            tag: span,
        };

        if long {
            if metadata.is_some() {
                record.push(
                    "target",
                    if metadata_is_symlink(metadata) {
                        if let Ok(path_to_link) = file_info.path.read_link() {
                            Value::string(path_to_link.to_string_lossy(), span)
                        } else {
                            Value::string("Could not obtain target file's path", span)
                        }
                    } else {
                        Value::nothing(span)
                    },
                );
            }
        }

        if long {
            if let Some(md) = metadata {
                record.push("readonly", Value::bool(metadata_readonly(md), span));

                #[cfg(unix)]
                {
                    let unix_meta = unix_listing_numbers(md);
                    record.push(
                        "mode",
                        Value::string(umask::Mode::from(unix_meta.mode).to_string(), span),
                    );
                    record.push("num_links", Value::int(unix_meta.nlink as i64, span));
                    record.push("inode", Value::int(unix_meta.ino as i64, span));

                    use nu_utils::filesystem::users;
                    record.push(
                        "user",
                        if let Some(user) = users::get_user_by_uid(unix_meta.uid.into()) {
                            Value::string(user.name, span)
                        } else {
                            Value::int(unix_meta.uid.into(), span)
                        },
                    );
                    record.push(
                        "group",
                        if let Some(group) = users::get_group_by_gid(unix_meta.gid.into()) {
                            Value::string(group.name, span)
                        } else {
                            Value::int(unix_meta.gid.into(), span)
                        },
                    );
                }
            }
        }

        record.push(
            "size",
            if should_use_recursive_dir_size(metadata, du) {
                let params = DirBuilder::new(self.tag, None, self.deref, None, false);
                let dir_info = DirInfo::new(&file_info.path, &params, None, span, signals)?;
                Value::filesize(dir_info.size as i64, dir_info.tag)
            } else if file_info.blocks.is_some() {
                Value::filesize(file_info.size as i64, file_info.tag)
            } else if metadata.is_some() {
                Value::nothing(span)
            } else {
                Value::nothing(span)
            },
        );

        push_timestamps(&mut record, metadata, span, long);

        Ok(Value::record(record, span))
    }
}

#[derive(Debug, Clone)]
pub struct DirInfo {
    dirs: Vec<DirInfo>,
    files: Vec<FileInfo>,
    errors: Vec<ShellError>,
    size: u64,
    blocks: u64,
    path: PathBuf,
    tag: Span,
}

#[derive(Debug, Clone)]
pub struct FileInfo {
    path: PathBuf,
    size: u64,
    blocks: Option<u64>,
    tag: Span,
}

impl FileInfo {
    pub fn new(path: impl Into<PathBuf>, deref: bool, tag: Span) -> Result<Self, ShellError> {
        let path = path.into();
        let m = if deref {
            std::fs::metadata(&path)
        } else {
            std::fs::symlink_metadata(&path)
        };

        match m {
            Ok(d) => {
                let block_size = file_real_size_fast(&path, &d).ok();

                Ok(FileInfo {
                    path,
                    blocks: block_size,
                    size: d.len(),
                    tag,
                })
            }
            Err(e) => Err(e.into()),
        }
    }
}

impl DirInfo {
    pub fn new(
        path: impl Into<PathBuf>,
        params: &DirBuilder,
        depth: Option<u64>,
        span: Span,
        signals: &Signals,
    ) -> Result<Self, ShellError> {
        let path = path.into();

        let mut s = Self {
            dirs: Vec::new(),
            errors: Vec::new(),
            files: Vec::new(),
            size: 0,
            blocks: 0,
            tag: params.tag,
            path,
        };

        match std::fs::metadata(&s.path) {
            Ok(d) => {
                s.size = d.len(); // dir entry size
                s.blocks = file_real_size_fast(&s.path, &d).ok().unwrap_or(0);
            }
            Err(e) => s = s.add_error(e.into()),
        };

        match std::fs::read_dir(&s.path) {
            Ok(d) => {
                for f in d {
                    signals.check(span)?;

                    match f {
                        Ok(i) => match i.file_type() {
                            Ok(t) if t.is_dir() => {
                                s = s.add_dir(i.path(), depth, params, span, signals)?
                            }
                            Ok(_t) => s = s.add_file(i.path(), params),
                            Err(e) => s = s.add_error(e.into()),
                        },
                        Err(e) => s = s.add_error(e.into()),
                    }
                }
            }
            Err(e) => s = s.add_error(e.into()),
        }
        Ok(s)
    }

    fn add_dir(
        mut self,
        path: impl Into<PathBuf>,
        mut depth: Option<u64>,
        params: &DirBuilder,
        span: Span,
        signals: &Signals,
    ) -> Result<Self, ShellError> {
        if let Some(current) = depth {
            if let Some(new) = current.checked_sub(1) {
                depth = Some(new);
            } else {
                return Ok(self);
            }
        }

        let d = DirInfo::new(path, params, depth, span, signals)?;
        self.size += d.size;
        self.blocks += d.blocks;
        self.dirs.push(d);
        Ok(self)
    }

    fn add_file(mut self, f: impl Into<PathBuf>, params: &DirBuilder) -> Self {
        let f = f.into();
        let include = params
            .exclude
            .as_ref()
            .map_or(true, |x| !x.matches_path(&f));
        if include {
            match FileInfo::new(f, params.deref, self.tag) {
                Ok(file) => {
                    let inc = params.min.map_or(true, |s| file.size >= s);
                    if inc {
                        self.size += file.size;
                        self.blocks += file.blocks.unwrap_or(0);

