) -> Result<Box<dyn Iterator<Item = Result<PathBuf, ShellError>> + Send>, ShellError> {
    let iter = f.read_dir()?.map(|d| {
        d.map(|r| r.path())
            .map_err(|e| ShellError::IOError { msg: e.to_string() })
    });
    Ok(Box::new(iter))
}

